INSERT INTO roast_profiles (id, name, description, is_public, target_total_time, target_first_crack, target_end_temp, charge_temp, roast_level, roast_purpose) VALUES ('fluidbed-nordic', 'Fluid bed — Extra-light filter (Nordic)', 'Very light, Nordic-style filter roast: drop about a minute after first crack to keep acidity and florals. FC ~7:30 at ~200 °C, drop 8:30 at 205 °C (development 1:00, ~12 %). Cold charge; declining RoR.', 1, 510, 450, 205.0, 30.0, 'extremely_light', 'filter') ON CONFLICT(id) DO UPDATE SET name = excluded.name, description = excluded.description, target_total_time = excluded.target_total_time, target_first_crack = excluded.target_first_crack, target_end_temp = excluded.target_end_temp, charge_temp = excluded.charge_temp, roast_level = excluded.roast_level, roast_purpose = excluded.roast_purpose;
