INSERT INTO roast_profiles (id, name, description, is_public, target_total_time, target_first_crack, target_end_temp, charge_temp, roast_level, roast_purpose) VALUES ('fluidbed-cupping', 'Fluid bed — Cupping (SCA sample roast)', 'Sample roast for cupping green coffees, after the SCA protocol: 8-12 minutes to about Agtron 63 ground. FC ~8:00 at ~200 °C, drop 10:00 at 213 °C (development 2:00, ~20 %). Cold charge; declining RoR.', 1, 600, 480, 213.0, 30.0, 'medium_light', 'other') ON CONFLICT(id) DO UPDATE SET name = excluded.name, description = excluded.description, target_total_time = excluded.target_total_time, target_first_crack = excluded.target_first_crack, target_end_temp = excluded.target_end_temp, charge_temp = excluded.charge_temp, roast_level = excluded.roast_level, roast_purpose = excluded.roast_purpose;
