INSERT INTO roast_profiles (id, name, description, is_public, target_total_time, target_first_crack, target_end_temp, charge_temp, roast_level, roast_purpose) VALUES ('fluidbed-espresso-short', 'Fluid bed — Light espresso, short development', 'Light espresso with a development inside what a light roast expects (1:00-2:00): an alternative to the longer Light espresso when roasts come out dark. FC ~8:30 at ~200 °C, drop 10:15 at 210 °C (development 1:45, ~17 %). Cold charge; declining RoR.', 1, 615, 510, 210.0, 30.0, 'light', 'espresso') ON CONFLICT(id) DO UPDATE SET name = excluded.name, description = excluded.description, target_total_time = excluded.target_total_time, target_first_crack = excluded.target_first_crack, target_end_temp = excluded.target_end_temp, charge_temp = excluded.charge_temp, roast_level = excluded.roast_level, roast_purpose = excluded.roast_purpose;
